  'Lets you sign in with it instead of your name. Nothing is ever sent to it.': 'ให้คุณเข้าสู่ระบบด้วยอีเมลแทนชื่อได้ ไม่มีการส่งอะไรไปที่อีเมลนี้เลย',
  'That is not an e-mail address.': 'นี่ไม่ใช่ที่อยู่อีเมล',
