  'Sign-in e-mail': 'อีเมลสำหรับเข้าสู่ระบบ',
  'Sign in with “{0}” instead of your name': 'เข้าสู่ระบบด้วย “{0}” แทนชื่อของคุณ',
  '“{0}” is saved, but signs in only once this profile has a password.': 'บันทึก “{0}” ไว้แล้ว แต่จะใช้เข้าสู่ระบบได้เมื่อโปรไฟล์นี้มีรหัสผ่านเท่านั้น',
  'Not set. Lets you sign in with an e-mail instead of your name.': 'ยังไม่ได้ตั้ง ช่วยให้เข้าสู่ระบบด้วยอีเมลแทนชื่อได้',
  'Change sign-in e-mail': 'เปลี่ยนอีเมลสำหรับเข้าสู่ระบบ',
  'Add a sign-in e-mail': 'เพิ่มอีเมลสำหรับเข้าสู่ระบบ',
  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': 'พิมพ์อีเมลนี้ที่ “เข้าสู่ระบบด้วยรหัสผ่าน” แทนชื่อโปรไฟล์ เราไม่ส่งอะไรไปที่อีเมลนี้เลย ถ้าลืมรหัสผ่าน แอดมินยังคงเป็นผู้รีเซ็ตให้',
  'E-mail address': 'ที่อยู่อีเมล',
  'That is already your sign-in e-mail.': 'นี่เป็นอีเมลสำหรับเข้าสู่ระบบของคุณอยู่แล้ว',
  'E-mail saved': 'บันทึกอีเมลแล้ว',
  'Remove e-mail': 'ลบอีเมล',
  'Remove your sign-in e-mail?': 'ลบอีเมลสำหรับเข้าสู่ระบบหรือไม่',
  'Afterwards you sign in with your profile name only.': 'หลังจากนั้นคุณจะเข้าสู่ระบบด้วยชื่อโปรไฟล์เท่านั้น',
  'E-mail removed': 'ลบอีเมลแล้ว',
  'Too many attempts. Try again {0}.': 'ลองหลายครั้งเกินไป ลองใหม่อีกครั้ง{0}',
  'Use at least {0} characters.': 'ใช้อย่างน้อย {0} ตัวอักษร',
