  'Language': 'ภาษา',
  'Exercise instructions aren\'t translated into this language yet, so they stay in English.': 'คำแนะนำท่าออกกำลังกายยังไม่ได้แปลเป็นภาษานี้ จึงแสดงเป็นภาษาอังกฤษไปก่อน',
