  'How hard was that set?': 'เซ็ตนั้นหนักแค่ไหน?',
  'Tap how many reps you had left, or type an exact {0}.': 'แตะเลือกว่าเหลืออีกกี่ครั้ง หรือพิมพ์ค่า {0} ที่แน่นอน',
  'Exact {0}': '{0} ที่แน่นอน',
  'Clear rating': 'ล้างการประเมิน',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR นับจำนวนครั้งที่ยังเหลือแรงทำได้ ส่วน RPE วัดความหนักเดียวกันบนสเกล 10 ระดับ ดังนั้น RPE ≈ 10 − RIR เลือกแบบที่คุณคุ้นอยู่แล้วได้เลย',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'แถวที่ไฮไลต์คือช่วงที่เซ็ตหลักส่วนใหญ่มักอยู่ เซ็ตที่บันทึกไปแล้วจะคงมาตรวัดเดิมไว้ และไม่มีส่วนอื่นนำค่านี้ไปใช้ การเพิ่มน้ำหนักและ 1RM โดยประมาณจึงไม่ได้รับผลกระทบ',
