  'Every muscle group got at least one hard set in this period.': 'ทุกกลุ่มกล้ามเนื้อได้เซ็ตหนักอย่างน้อยหนึ่งเซ็ตในช่วงนี้',
  'No rated sets in this period.': 'ไม่มีเซ็ตที่ให้คะแนนในช่วงนี้',
