  'Week by week': 'รายสัปดาห์',
  'Where the sets land': 'เซ็ตส่วนใหญ่อยู่ระดับไหน',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'เซ็ตหลักส่วนใหญ่ควรอยู่ใกล้จุดหมดแรง ไม่ใช่ถึงจุดนั้น ครึ่งหนึ่งต่ำสุดกับอีกครึ่งสูงสุด เฉลี่ยแล้วก็ยังดูเหมือนอยู่ตรงกลางสวยๆ อยู่ดี',
  'Average effort per workout': 'ความหนักเฉลี่ยต่อครั้ง',
  'A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.': 'จุดที่เต็มกว่าหมายถึงเหลือแรงน้อยกว่า น้ำหนักเท่าเดิมที่ {0} ต่ำกว่าคือความคืบหน้าที่กราฟเส้นอย่างเดียวไม่บอก',
  // --- bodyweight & per side ---
  'Bodyweight': 'น้ำหนักตัว',
  'No weight to enter. Just log the reps.': 'ไม่ต้องกรอกน้ำหนัก บันทึกแค่จำนวนครั้งพอ',
