  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'โค้ชไม่ใช่แพทย์หรือนักกายภาพบำบัด หากมีอาการเจ็บ โปรดปรึกษาผู้เชี่ยวชาญ',
