  'The Coach needs your go-ahead first.': 'โค้ชต้องได้รับความยินยอมจากคุณก่อน',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'คีย์ถูกเก็บในที่จัดเก็บที่ปลอดภัยของโทรศัพท์นี้ และไม่ออกไปไหนนอกจากเพื่อเรียกผู้ให้บริการ',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'โทรศัพท์นี้เรียกผู้ให้บริการโดยตรงด้วยคีย์ของคุณ ทุกคำขอจะถูกเรียกเก็บจากบัญชีของคุณ',
  'Turn the Coach off on this phone': 'ปิดโค้ชบนโทรศัพท์นี้',
  'Use my self-hosted openGym': 'ใช้ openGym ที่ฉันโฮสต์เอง',
  'What leaves this phone': 'อะไรที่ออกจากโทรศัพท์นี้',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'เซิร์ฟเวอร์ของคุณไม่ได้เปิดโค้ช ถามผู้ดูแล หรือใช้คีย์ของคุณเองด้านล่าง',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'เซิร์ฟเวอร์ของคุณเรียกใช้โค้ชด้วยผู้ให้บริการที่ผู้ดูแลตั้งค่าไว้ ไม่มีข้อมูลใหม่ออกจากโทรศัพท์นี้นอกเหนือจากที่ซิงค์อยู่แล้ว',
  'Loading the exercise catalogue…': 'กำลังโหลดคลังท่าออกกำลังกาย…',
  'Checking the endpoint…': 'กำลังตรวจสอบปลายทาง…',
  'A local model can take longer.': 'โมเดลในเครื่องอาจใช้เวลานานกว่า',
