  'Done! Your plan is back to how it was before my last changes.': 'เรียบร้อย! แผนของคุณกลับไปเป็นเหมือนก่อนที่ฉันจะเปลี่ยนครั้งล่าสุดแล้ว',
  'Edit my answers': 'แก้ไขคำตอบของฉัน',
