  'Here is what I am working with:': 'นี่คือข้อมูลที่ฉันใช้อยู่:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'สวัสดี ฉันคือโค้ชของคุณ ฉันสร้างแผนจากคำตอบของคุณ และปรับตามสิ่งที่คุณบันทึกจริง ไม่มีอะไรเปลี่ยนจนกว่าคุณจะตกลง',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'ฉันดูทั้งหมดแล้ว ตอนนี้ไม่มีอะไรที่อยากเปลี่ยนเลย ทำแบบนี้ต่อไป แล้วถามฉันใหม่หลังฝึกอีกสักสองสามครั้ง',
  'I understand, let’s go': 'เข้าใจแล้ว ไปกันเลย',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'นำเข้าแล้ว! {0} รูทีนอยู่ในแผนของคุณ และจัดสัปดาห์ให้เรียบร้อยแล้ว เจอกันเซสชันหน้า',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'นำเข้าแล้ว! {0} รูทีนอยู่ในแผนของคุณ สัปดาห์ของคุณยังเหมือนเดิม จัดตารางได้ตามสะดวก',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'มันออกแบบแผนของคุณจากคำตอบไม่กี่ข้อและปรับตามสิ่งที่คุณบันทึกจริง ไม่เปลี่ยนแปลงอะไรโดยไม่ได้รับความยินยอม และคุณเลิกทำทุกการเปลี่ยนแปลงได้',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'รูทีน ท่าออกกำลังกาย เซ็ตและจำนวนครั้ง ตารางรายสัปดาห์ของคุณ และการตั้งค่าการเพิ่มระดับ',
  'Your logged training': 'การฝึกที่คุณบันทึก',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'เซ็ตที่คุณบันทึกในช่วงรีวิว: น้ำหนัก จำนวนครั้ง เวลา คะแนนความหนัก ระยะเวลาของแต่ละเซสชัน และบันทึกประจำรอบของคุณ',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'บันทึกน้ำหนักจากช่วงเดียวกัน และน้ำหนักเป้าหมายของคุณ หากตั้งไว้',
