  'This workout was deleted on another device. Your edits are still here.': 'การออกกำลังกายนี้ถูกลบในอุปกรณ์อื่น การแก้ไขของคุณยังอยู่ที่นี่',
  'Close editor': 'ปิดตัวแก้ไข',
  'Editing a saved workout. Date and duration stay unchanged.': 'กำลังแก้ไขการออกกำลังกายที่บันทึกไว้ วันที่และระยะเวลาจะไม่เปลี่ยน',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'ท่าดึงหนึ่งท่าต่อท่าดันทุกท่า เพื่อให้หัวไหล่สมดุล',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'การสลับสองวันใน 3 เซสชันต่อสัปดาห์ ออกแบบตามอุปกรณ์ที่คุณระบุ ท่าคอมปาวด์ก่อน ท่าดึงหนึ่งท่าต่อท่าดันทุกท่า และให้แต่ละวันทับซ้อนกันพอที่จะไม่มีส่วนไหนถูกเว้นการฝึกนานสองสัปดาห์',
  'Based on the training already in this demo profile.': 'อิงจากการฝึกที่มีอยู่แล้วในโปรไฟล์เดโมนี้',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'น้ำหนักตัวนิ่งมาสี่สัปดาห์แล้ว ทั้งที่เป้าหมายคือเพิ่มน้ำหนัก นี่เป็นเรื่องในครัว ไม่ใช่เรื่องการฝึก แผนไม่ใช่ตัวที่ฉุดไว้',
  'Demo': 'เดโม',
  'Demo data reset': 'รีเซ็ตข้อมูลเดโมแล้ว',
  'Direct arm work, since you asked for it.': 'ฝึกแขนโดยตรง เพราะคุณขอไว้',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'เซ็ตหลักทุกเซ็ตของท่านี้อยู่ที่ RPE 9.5 ขึ้นไปติดต่อกันสามเซสชัน และน้ำหนักไม่ขยับเลย การเปลี่ยนท่าสักสี่สัปดาห์มักทำลายจุดตันได้เร็วกว่าการฝืนท่าเดิม',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'ข้อมูลตัวอย่าง เก็บไว้ในเบราว์เซอร์นี้เท่านั้น จัดเต็มได้เลย เปลี่ยนอะไรก็ได้ตามใจ',
  'Full body A': 'ทั้งตัว A',
  'Full body B': 'ทั้งตัว B',
  'Horizontal pressing, the other half of the session.': 'ท่าดันแนวนอน อีกครึ่งหนึ่งของเซสชัน',
  'Live demo. Everything stays in this browser.': 'เดโมสด ทุกอย่างอยู่ในเบราว์เซอร์นี้',
  'No training history yet, so starting conservatively.': 'ยังไม่มีประวัติการฝึก จึงเริ่มแบบระมัดระวัง',
  'Passkey sign-in, sync across your devices, your own data.': 'ลงชื่อเข้าใช้ด้วยพาสคีย์ ซิงก์ข้ามอุปกรณ์ของคุณ ข้อมูลเป็นของคุณเอง',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'คืนแผน การฝึก และการชั่งน้ำหนักตัวอย่างกลับเป็นเหมือนตอนเริ่มต้น',
  'Reset': 'รีเซ็ต',
  'Reset demo data': 'รีเซ็ตข้อมูลเดโม',
  'Reset demo data?': 'รีเซ็ตข้อมูลเดโม?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'ปรับตามที่คุณขอแล้ว ส่วนที่คุณไม่ได้ติงไว้ยังคงเหมือนเดิมทุกอย่าง',
  'Same pattern, higher reps than day A.': 'รูปแบบเดิม จำนวนครั้งมากกว่าวัน A',
  'Self-host it in a minute →': 'โฮสต์เองได้ในหนึ่งนาที →',
  'Self-host openGym': 'โฮสต์ openGym เอง',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'เซสชันเกินเวลาไปราวสิบห้านาที ท่าเสริมนี้เสียน้อยที่สุดหากลดลงหนึ่งเซ็ต',
  'Start the demo': 'เริ่มเดโม',
  'The main lower-body driver, where most of the strength comes from.': 'ท่าหลักของร่างกายส่วนล่าง แรงส่วนใหญ่มาจากตรงนี้',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'รูปแบบเดิม แต่ต่างวิธีทำ: ทับซ้อนพอให้ก้าวหน้า ต่างพอให้ไม่จำเจ',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'ทำสองรูปแบบใหญ่ของร่างกายส่วนล่างและท่าดันก่อน ขณะที่ยังสดอยู่',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'เดโมนี้ทำงานในเบราว์เซอร์ของคุณทั้งหมดด้วยข้อมูลตัวอย่าง ไม่มีอะไรถูกส่งออกไปไหน การเข้าสู่ระบบด้วยพาสคีย์และการซิงก์ข้ามอุปกรณ์มาพร้อมเซิร์ฟเวอร์ openGym ซึ่งคุณได้มาด้วยการโฮสต์เอง',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'มีสามอย่างที่ควรเปลี่ยน และอีกหนึ่งอย่างที่ควรรู้ ที่เหลือไปได้ดี: ทั้งสควอตและท่าดึงก้าวหน้าตามแผน',
  'Vertical pressing.': 'ท่าดันแนวตั้ง',
