  'Nothing syncs until you say whether this device’s workouts go into your profile. Tap to answer.': 'จะยังไม่ซิงค์อะไรจนกว่าคุณจะบอกว่าจะให้การออกกำลังกายในอุปกรณ์นี้เข้าไปอยู่ในโปรไฟล์หรือไม่ แตะเพื่อตอบ',
