  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'ผู้ให้บริการ AI ของโค้ชปฏิเสธรูปแบบคำขอ เจ้าของอินสแตนซ์ต้องลองโมเดลอื่น',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'ผู้ให้บริการ AI ของโค้ชขัดข้องอยู่ ลองใหม่อีกสักครู่',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'โค้ชติดต่อผู้ให้บริการ AI ไม่ได้ เจ้าของอินสแตนซ์ต้องตรวจสอบปลายทางและเครือข่าย',
