  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'วันนี้เหนื่อยเหรอ? {0} รอได้ พรุ่งนี้เริ่มใหม่',
  'Hey, {0} didn’t happen today. All good?': 'เฮ้ วันนี้ไม่ได้เล่น {0} ทุกอย่างโอเคไหม?',
