  'Quick arrival check': 'ตรวจการมาถึงแบบเร็ว',
  'Near a gym, the phone takes a short GPS look (a few minutes at most) so the nudge comes at the door.': 'เมื่อใกล้ยิม โทรศัพท์จะเปิด GPS ดูแป๊บหนึ่ง (อย่างมากไม่กี่นาที) การแจ้งเตือนจะมาถึงตอนอยู่หน้าประตู',
  'Android can take up to half an hour to notice you walked in. Set openGym’s battery use to Unrestricted and the phone takes a short GPS look when you get near a gym, so the nudge comes at the door.': 'Android อาจใช้เวลาถึงครึ่งชั่วโมงกว่าจะรู้ว่าคุณมาถึงแล้ว ตั้งการใช้แบตเตอรี่ของ openGym เป็น "ไม่จำกัด" แล้วโทรศัพท์จะเปิด GPS ดูแป๊บหนึ่งเมื่อใกล้ยิม การแจ้งเตือนจะมาถึงตอนอยู่หน้าประตู',
  'Gym spotted': 'เจอยิมแล้ว',
  'Leave it empty for the default.': 'เว้นว่างไว้เพื่อใช้ข้อความเริ่มต้น',
  'Location access': 'การเข้าถึงตำแหน่ง',
  'Location isn’t allowed for openGym. You can change that in the phone’s settings.': 'openGym ไม่ได้รับอนุญาตให้ใช้ตำแหน่ง เปลี่ยนได้ในการตั้งค่าของมือถือ',
  'My gym': 'ยิมของฉัน',
  'Name': 'ชื่อ',
  'No more nudges when you arrive here.': 'จะไม่มีการสะกิดอีกเมื่อคุณมาถึงที่นี่',
  'Not asked yet': 'ยังไม่ได้ถาม',
