  'Notifications are off for openGym, so the reminder has nowhere to show up.': 'การแจ้งเตือนของ openGym ปิดอยู่ การเตือนจึงไม่มีที่ให้แสดง',
  'On the next screen, pick “Allow all the time”.': 'ในหน้าถัดไป เลือก “อนุญาตตลอดเวลา”',
