  'Your gym': 'ยิมของคุณ',
  'Lost access?': 'เข้าใช้งานไม่ได้?',
  'No panic: your training is safe on the server. One of these gets you back in.': 'ไม่ต้องกังวล การฝึกของคุณปลอดภัยอยู่บนเซิร์ฟเวอร์ วิธีใดวิธีหนึ่งต่อไปนี้จะพาคุณกลับเข้ามา',
  'Your passkey may be synced': 'พาสคีย์ของคุณอาจซิงค์อยู่แล้ว',
  'Passkeys kept in iCloud Keychain, Google Password Manager or a password manager are on your other devices too. Try “Sign in with passkey” there.': 'พาสคีย์ที่เก็บใน iCloud Keychain, Google Password Manager หรือโปรแกรมจัดการรหัสผ่านจะอยู่ในอุปกรณ์อื่นของคุณด้วย ลอง “เข้าสู่ระบบด้วยพาสคีย์” ที่นั่น',
  'Another device still signed in?': 'มีอุปกรณ์อื่นที่ยังเข้าสู่ระบบอยู่ไหม',
  'On that one, open Settings → Account → Add another device, then enter its code here with “I have a code”.': 'ที่เครื่องนั้น เปิด ตั้งค่า → บัญชี → เพิ่มอุปกรณ์อื่น แล้วใส่รหัสที่นี่ผ่าน “ฉันมีรหัส”',
  'Ask your admin': 'ถามผู้ดูแลระบบ',
  'Whoever runs your openGym server can make you a recovery code in the admin dashboard. Enter it with “I have a code”, and this device gets a new passkey.': 'ผู้ที่ดูแลเซิร์ฟเวอร์ openGym ของคุณสร้างรหัสกู้คืนให้ได้ในแดชบอร์ดผู้ดูแล ใส่รหัสผ่าน “ฉันมีรหัส” แล้วอุปกรณ์นี้จะได้พาสคีย์ใหม่',
  'Running the server yourself?': 'คุณดูแลเซิร์ฟเวอร์เองหรือเปล่า',
  'Get a recovery code for any profile, the owner’s too, on the server: docker compose exec api node recover.js "Your name"': 'ขอรหัสกู้คืนของโปรไฟล์ใดก็ได้บนเซิร์ฟเวอร์ รวมถึงของเจ้าของ: docker compose exec api node recover.js "ชื่อของคุณ"',
  'In this app: enter the code on your openGym site in a browser, then pair the app again from Settings → Account there.': 'ในแอปนี้: ใส่รหัสในเว็บ openGym ของคุณผ่านเบราว์เซอร์ แล้วจับคู่แอปใหม่จาก ตั้งค่า → บัญชี ที่นั่น',
  'I have a code': 'ฉันมีรหัส',
  'A recovery code from your admin goes here too.': 'รหัสกู้คืนจากผู้ดูแลก็ใส่ที่นี่ได้',
  'A day off before the next one': 'หยุดหนึ่งวันก่อนรายการถัดไป',
  'Already in the loop: adds it again': 'อยู่ในรอบแล้ว: เพิ่มอีกครั้ง',
  'Rest day. The loop goes on {0}.': 'วันพัก รอบจะเริ่มต่อ {0}',
  'Support openGym': 'สนับสนุน openGym',
  'openGym is free: no ads, no subscriptions, no tracking. A coffee keeps it that way.': 'openGym ใช้ฟรี: ไม่มีโฆษณา ไม่มีสมาชิกรายเดือน ไม่มีการติดตาม กาแฟสักแก้วช่วยให้เป็นแบบนี้ต่อไป',
  'Rate openGym on the App Store': 'ให้คะแนน openGym ใน App Store',
  'Rate openGym on Google Play': 'ให้คะแนน openGym ใน Google Play',
  'Buy me a coffee': 'เลี้ยงกาแฟสักแก้ว',
  'Export as spreadsheet (CSV)': 'ส่งออกเป็นสเปรดชีต (CSV)',
  'Workouts, body weight and measurements': 'การออกกำลังกาย น้ำหนักตัว และสัดส่วน',
  'One row per set, for Excel, Sheets, your coach or another app. openGym reads it back too.': 'หนึ่งแถวต่อเซ็ต สำหรับ Excel, Sheets, โค้ชของคุณ หรือแอปอื่น openGym ก็อ่านกลับได้เหมือนกัน',
  'Workouts (CSV)': 'การออกกำลังกาย (CSV)',
