  "A few more weigh-ins, spread over the next days, and you get a weekly trend.": "ชั่งน้ำหนักอีกสักสองสามครั้งในวันถัดๆ ไป แล้วจะเห็นแนวโน้มรายสัปดาห์",
  "On pace": "ตามเป้า",
