  'Delete programme': 'ลบโปรแกรม',
  'Deload week': 'สัปดาห์ดีโหลด',
  'Each adds its own routines, so your plan stays as it is until you start it.': 'แต่ละโปรแกรมเพิ่มรูทีนของตัวเอง แผนของคุณจึงเหมือนเดิมจนกว่าจะเริ่ม',
  'Effort for the week': 'ความหนักของสัปดาห์',
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': 'เว้นว่างไว้ให้การเพิ่มระดับเลือกน้ำหนัก %1RM คำนวณจาก 1RM ประมาณการที่ดีที่สุดของคุณ',
  'End programme': 'จบโปรแกรม',
  'End “{0}”?': 'จบ "{0}" ไหม?',
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': 'สี่วัน การเพิ่มระดับเลือกน้ำหนัก ความหนักไต่ถึง RPE 9 แล้วดีโหลด',
  'Heavier means every %1RM goes up {0} points.': 'หนักขึ้นหมายถึง %1RM ทุกตัวเพิ่มขึ้น {0} จุด',
  'It is running: ending it brings your plan back. Its routines stay.': 'กำลังใช้อยู่: จบแล้วแผนของคุณจะกลับมา รูทีนยังอยู่',
  'Its routines stay.': 'รูทีนยังอยู่',
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': 'ตารางของมันใช้แทนแผนของคุณจนกว่าจะจบ แล้วแผนของคุณจะกลับมาเหมือนเดิม',
  'Lighter weights, and its sessions do not count toward progression.': 'น้ำหนักเบาลง และเซสชันไม่นับในการเพิ่มระดับ',
  'Linear 5×5 style, 12 weeks': 'แบบเส้นตรงสไตล์ 5×5, 12 สัปดาห์',
  'Log a set first to work this out': 'บันทึกเซ็ตก่อนจึงจะคำนวณได้',
