  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': 'สัปดาห์คือสัปดาห์ตามปฏิทิน: สัปดาห์ที่ 1 คือสัปดาห์ที่คุณเริ่ม การพักไว้จะหยุดไว้ก่อน',
