  "Muscles at a glance": "กล้ามเนื้อในพริบตา",
  "Narrow the list by body part, type or the equipment you have.": "กรองรายการตามส่วนของร่างกาย ประเภท หรืออุปกรณ์ที่คุณมี",
  "No thanks": "ไม่ล่ะ ขอบคุณ",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "เลือกท่าเพื่อดูเซ็ตที่ดีที่สุด ค่าสูงสุดโดยประมาณ และแนวโน้ม",
  "Pointing at: {0}": "ชี้ไปที่: {0}",
  "Practice run": "เซสชันลองเล่น",
  "Programmes and sharing": "โปรแกรมและการแชร์",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "โปรแกรม แผนเริ่มต้น และการแชร์แผนให้เพื่อน อยู่หลังปุ่มนี้",
  "Records": "สถิติสูงสุด",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "ตารางเวลาบอกว่าเมื่อไร รูทีนบอกว่าอะไร สร้างเองหรือหยิบแผนเริ่มต้นก็ได้",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "ท่าออกกำลังกายนับพันในภาษาของคุณ ติดดาวท่าโปรดแล้วมันจะขึ้นไปอยู่บนสุด",
  "See which muscles got the work and which still need rest. Tap one for details.": "ดูว่ากล้ามเนื้อไหนทำงาน และไหนยังต้องพัก แตะเพื่อดูรายละเอียด",
  "Show me": "ให้ดูหน่อย",
  "Show the tour again": "แสดงทัวร์อีกครั้ง",
  "Skip tour": "ข้ามทัวร์",
  "Step {0} of {1}": "ขั้นที่ {0} จาก {1}",
  "Swipe a set": "ปัดเซ็ต",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "ปัดเซ็ตไปด้านข้างเพื่อคัดลอกหรือลบ ตัวเลขของมันเปิดได้อีกเยอะ",
  "The big Start button": "ปุ่มเริ่มอันใหญ่",
  "The little body shows what each day works, so leg day can’t hide.": "ร่างกายเล็กๆ บอกว่าแต่ละวันฝึกอะไร วันขาจะซ่อนไม่ได้",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "การพักเริ่มเอง เพิ่มเวลา หรือข้ามไปถ้ารู้สึกเป็นฮีโร่",
  "The ⋯ menu": "เมนู ⋯",
  "Theme, accent colour and what Home shows.": "ธีม สีเน้น และสิ่งที่หน้าหลักแสดง",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "อันนี้ลองเล่น ไม่มีอะไรถูกบันทึก แต่ละแถวคือหนึ่งเซ็ต: น้ำหนัก แล้วจำนวนครั้ง แตะตัวเลขเพื่อเปลี่ยน",
  "Tick it off": "ติ๊กเลย",
  "Today at a glance": "วันนี้แบบย่อ",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "เซสชันวันนี้อยู่ตรงนี้ แตะครั้งเดียวก็เริ่มยก วันพักก็บอกว่าพัก ไม่ต้องรู้สึกผิด",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "ฝึกตามวันที่กำหนด หรือหมุนรูทีนเป็นวง อันถัดไปจะรอคุณ",
  "Want a 1-minute tour?": "ดูทัวร์ 1 นาทีไหม?",
  "Week or rotation": "สัปดาห์หรือการหมุนเวียน",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "เราจะชี้ของดีบนหน้าจอจริง ออกได้ทุกเมื่อ",
  "Workout settings, layouts, notes and extra exercises hide in here.": "การตั้งค่าเวิร์กเอาต์ เลย์เอาต์ โน้ต และท่าเพิ่มเติมซ่อนอยู่ในนี้",
