  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "อันนี้อยู่ในแอป openGym บนมือถือ: Apple Health บน iPhone และ Health Connect บน Android",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "เว็บฮุกส่งโดยเซิร์ฟเวอร์ openGym ของคุณเอง จึงต้องมีเซิร์ฟเวอร์ เชื่อมอุปกรณ์นี้ได้ที่บัญชี",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "เซิร์ฟเวอร์นี้ปิดเว็บฮุกไว้ เพิ่ม INTEGRATIONS=webhook ในไฟล์ .env แล้วรีสตาร์ต",
  "The MCP server runs next to your own openGym server and reads your data there.": "เซิร์ฟเวอร์ MCP ทำงานข้างเซิร์ฟเวอร์ openGym ของคุณและอ่านข้อมูลจากที่นั่น",
  "Only what you switch on talks to anything. The rest stays out of your way.": "มีแค่สิ่งที่คุณเปิดเท่านั้นที่คุยกับภายนอก ที่เหลือไม่มารบกวน",
  "Could not reach your server": "ติดต่อเซิร์ฟเวอร์ของคุณไม่ได้",
  "Tap to try again": "แตะเพื่อลองอีกครั้ง",
  "Disconnect {0}?": "ยกเลิกการเชื่อมต่อ {0} ไหม",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym จะหยุดเขียนและอ่าน สิ่งที่เขียนไปแล้วเก็บไว้เป็นข้อมูลของคุณหรือลบออกก็ได้",
  "Works with": "ใช้ร่วมกับ",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "ไม่ต้องเชื่อมต่อเพิ่ม: แอปเหล่านี้เขียนลง {0} แล้ว openGym อ่านจากที่นั่น",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "ไม่ต้องเชื่อมต่อเพิ่ม: แอปเหล่านี้เขียนลง Apple Health หรือ Health Connect แล้วแอป openGym บนมือถืออ่านจากที่นั่น",
  "{0} has no direct line to openGym, and it does not need one.": "{0} ไม่ได้ต่อตรงกับ openGym และก็ไม่จำเป็นต้องต่อ",
  "How it gets here": "ข้อมูลมาถึงที่นี่อย่างไร",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0} บันทึกลง Apple Health บน iPhone หรือ Health Connect บน Android แล้ว openGym อ่านจากที่นั่น",
