  "They live under Stats. Tap it.": "อยู่ใน “สถิติ” แตะเลย",
  "They’re on Home. Tap it.": "อยู่ที่หน้าหลัก แตะเลย",
  "This is your real plan now, if you want it. Save keeps it. Skip and it was never here.": "ถ้าคุณต้องการ นี่คือแผนจริงของคุณแล้ว “บันทึก” จะเก็บไว้ “ข้าม” แล้วก็เหมือนไม่เคยมีมาก่อน",
  "This one is for real: we build a routine together and it lands in your plan when you tap Save. Bail before that and nothing stays behind.": "รอบนี้ของจริง: เราจะสร้างรูทีนด้วยกัน และมันจะเข้าไปอยู่ในแผนเมื่อคุณแตะ “บันทึก” ออกก่อนหน้านั้นก็ไม่มีอะไรค้างไว้",
  "Tutorials": "บทแนะนำ",
  "Up one level": "ขึ้นไปหนึ่งระดับ",
  "Want more? Each of these is a short guided run. You’ll find them again in Settings → About & updates.": "อยากดูอีก? แต่ละอันเป็นการพาชมสั้นๆ หาได้อีกครั้งใน “ตั้งค่า → เกี่ยวกับและอัปเดต”",
  "We swapped in a practice copy with a pretend workout and weigh-in. Poke at anything, nothing here sticks.": "เราสลับเป็นสำเนาซ้อมที่มีการออกกำลังกายจำลองและบันทึกน้ำหนักจำลอง จิ้มอะไรก็ได้ ที่นี่ไม่มีอะไรติดค้าง",
  "Weigh-ins first": "บันทึกน้ำหนักก่อน",
  "Weight unit, plates and stack live here. Edit or delete the exercise from here too.": "หน่วยน้ำหนัก แผ่นน้ำหนัก และสแต็กอยู่ที่นี่ แก้ไขหรือลบท่านี้ก็ทำได้จากตรงนี้",
