  "When do you train it?": "จะฝึกวันไหน?",
  "Where your data goes in and out. We only point, nothing runs until you tap it yourself.": "ที่นี่คือทางเข้าออกของข้อมูลคุณ เราแค่ชี้ทาง ไม่มีอะไรทำงานจนกว่าคุณจะแตะเอง",
  "Workouts, weigh-ins and what can be fixed": "การออกกำลังกาย บันทึกน้ำหนัก และสิ่งที่แก้ได้",
  "Your data, your call. Back it up now and then, future you will be grateful.": "ข้อมูลของคุณ คุณตัดสินใจเอง สำรองไว้บ้างเป็นระยะ ตัวคุณในอนาคตจะขอบคุณ",
