  "Your sets, weigh-ins and measurements as CSV. Our importer reads it back too.": "เซ็ต บันทึกน้ำหนัก และการวัดสัดส่วนของคุณเป็น CSV ตัวนำเข้าของเราก็อ่านกลับได้ด้วย",
