  "That didn’t work. Hold your phone still on the sticker and try again.": "ไม่สำเร็จ ถือโทรศัพท์นิ่งๆ บนสติกเกอร์แล้วลองอีกครั้ง",
  "This sticker can’t hold a link. Try an NTAG sticker.": "สติกเกอร์นี้เก็บลิงก์ไม่ได้ ลองใช้สติกเกอร์ NTAG",
