  "Follows Settings → Workout → Automatic warm-ups.": "ตามการตั้งค่า → เวิร์กเอาต์ → วอร์มอัพอัตโนมัติ",
  "For this workout": "สำหรับเวิร์กเอาต์นี้",
  "Heavy lifts get more rungs, light ones one or none.": "ท่าหนักได้หลายขั้น ท่าเบาได้ขั้นเดียวหรือไม่มีเลย",
  "It hurts": "เจ็บ",
  "It hurts, it’s taken, no time, feeling great": "เจ็บ, เครื่องไม่ว่าง, ไม่มีเวลา, รู้สึกดี",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "รู้สึกตึง ที่เหลือเลยเบาลง ถ้ายังเจ็บให้หยุด",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "รู้สึกตึง เซ็ตที่เหลือเลยย้ายไปท่าที่ใช้กล้ามเนื้อเดิมในมุมที่ถนอมกว่า",
  "Keep these warm-ups": "เก็บวอร์มอัพชุดนี้ไว้",
  "Kept. Same warm-ups next time, scaled to your work weight.": "เก็บแล้ว ครั้งหน้าวอร์มอัพแบบเดิม ปรับตามน้ำหนักทำงาน",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "เซ็ตที่บันทึกแล้วและรูทีนของคุณยังคงเดิม โค้ชไม่ใช่แพทย์หรือนักกายภาพบำบัด ถ้าเจ็บตรงไหนให้ปรึกษาผู้เชี่ยวชาญ",
  "Looking at your workout…": "กำลังดูเวิร์กเอาต์ของคุณ…",
  "Machine’s taken": "เครื่องไม่ว่าง",
  "My own": "ของฉันเอง",
  "New programme “{0}”": "โปรแกรมใหม่ “{0}”",
  "Nothing at {0} {1}: that one starts cold.": "ที่ {0} {1} ไม่มี: ท่านี้เริ่มเลย",
  "Nothing could be applied any more.": "ไม่มีอะไรที่ใช้ได้แล้ว",
  "Nothing to change. Carry on as planned.": "ไม่ต้องเปลี่ยนอะไร ทำต่อตามแผน",
  "One set less keeps the session doable today and still counts.": "ลดหนึ่งเซ็ต วันนี้ก็ยังทำไหวและยังนับอยู่",
  "Only the warm-ups you plan yourself.": "เฉพาะวอร์มอัพที่คุณวางแผนเอง",
  "Ramped from the work weight: more rungs when it is heavy, fewer when it is light.": "ไต่จากน้ำหนักทำงาน: หนักมีหลายขั้น เบามีน้อยขั้น",
  "Remove warm-up {0}": "ลบวอร์มอัพ {0}",
  "Revise programme “{0}”": "ปรับโปรแกรม “{0}”",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "รูทีน ท่า เซ็ตและจำนวนครั้ง วอร์มอัพ โปรแกรม ตารางรายสัปดาห์ การตั้งค่าการเพิ่มน้ำหนัก และน้ำหนักที่ยิมของคุณใส่ได้",
  "Running on empty": "หมดแรง",
  "Saved in the routine, scaled to your work weight": "บันทึกในรูทีน ปรับตามน้ำหนักทำงาน",
  "Saved under Plan → Programmes. It starts when you start it.": "บันทึกไว้ที่ แผน → โปรแกรม เริ่มเมื่อคุณกดเริ่ม",
  "Short on time": "เวลาน้อย",
  "Skip the rest of {0}": "ข้ามที่เหลือของ {0}",
  "Something else": "อย่างอื่น",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "สควอต เพรส โรว์ และเพื่อนๆ ได้ขั้นไต่ ส่วนเคิร์ลและเรสเริ่มเลย",
  "Straight into the work sets.": "เข้าเซ็ตทำงานเลย",
  "That workout is over, so these can’t be applied any more.": "เวิร์กเอาต์นั้นจบแล้ว ใช้คำแนะนำเหล่านี้ไม่ได้แล้ว",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "แอปไต่จากน้ำหนักทำงาน: หนักก็วอร์มอัพมากขึ้น เบาก็น้อยลง ด้วยแผ่นน้ำหนักของยิมคุณ",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "แร็กไม่ว่าง ทำท่านี้ตอนท้าย ที่เหลือของเซสชันไม่ต้องใช้",
  "There’s no workout running.": "ไม่มีเวิร์กเอาต์ที่กำลังทำอยู่",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "วอร์มอัพเหล่านี้มาก่อนเซ็ตทำงานทุกครั้ง เป็นสัดส่วนของน้ำหนักทำงาน จึงเพิ่มตามไปด้วย",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "นี่คือเดโม จึงไม่มีโมเดล AI อยู่เบื้องหลัง บนเซิร์ฟเวอร์ของคุณเอง ฉันจะอ่านเซสชันแล้วแนะนำการเปลี่ยนแปลงแบบนี้",
  "Warm-up {0}": "วอร์มอัพ {0}",
  "Warm-ups": "วอร์มอัพ",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "เกิดอะไรขึ้น? โค้ชจะแนะนำการปรับเปลี่ยนสำหรับส่วนที่เหลือของเวิร์กเอาต์นี้ เซ็ตที่บันทึกแล้วยังคงเดิม",
  "Where, and what movement hurts? (optional)": "เจ็บตรงไหน และท่าไหน? (ไม่บังคับ)",
  "With {0} {1} today: {2}": "ที่ {0} {1} วันนี้: {2}",
  "You can keep training, the answer waits here and in the Coach.": "เล่นต่อได้เลย คำตอบจะรออยู่ที่นี่และในหน้าโค้ช",
