  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "วางแผนไว้แต่ไม่ได้ฝึก ไม่เป็นไร คุณฝึกวันอื่นแล้ว สัปดาห์นั้นจึงยังนับ",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "เก็บตัวหยุดได้ 1 อัน ได้ทุก 4 สัปดาห์ที่ฝึก พลาด 2 สัปดาห์ติดกัน สถิติจะจบ",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "เก็บตัวหยุดได้สูงสุด 2 อัน ได้ทุก 4 สัปดาห์ที่ฝึก พลาด 2 สัปดาห์ติดกันก็ยังช่วยได้",
