  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "พลาดไปหนึ่งสัปดาห์? ตัวหยุดจะช่วยไว้: สถิติยังต่อเนื่อง แค่สัปดาห์นั้นไม่บวกเพิ่ม พลาด 2 สัปดาห์ติดกัน จะเริ่มนับใหม่",
  "No freezes": "ไม่มีตัวหยุด",
