  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} ให้คุณผ่านแล้ว แต่เซิร์ฟเวอร์นี้รับเฉพาะบางกลุ่ม ขอให้คนที่ดูแลเพิ่มคุณเข้าไป",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} ส่งสิ่งที่เราตรวจสอบไม่ได้กลับมา จึงไม่มีใครเข้าสู่ระบบ ถ้าเกิดซ้ำ หน้าแอดมินจะบอกสาเหตุ",
