  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "คาร์ดิโออัปโหลดตามที่เป็น: วิ่ง ปั่น พาย ส่วนการฝึกแรงขึ้นเป็น เวทเทรนนิ่ง พร้อมทุกเซ็ตในคำอธิบาย",
  "Change server or password": "เปลี่ยนเซิร์ฟเวอร์หรือรหัสผ่าน",
  "Check the connection": "ตรวจสอบการเชื่อมต่อ",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "เชื่อมต่อ Strava ครั้งเดียวจาก openGym ในเบราว์เซอร์ โดยลงชื่อเข้าใช้เซิร์ฟเวอร์ของคุณไว้ จากนั้นการฝึกจะอัปโหลดจากเซิร์ฟเวอร์ ไม่ว่าคุณจะบันทึกบนอุปกรณ์ไหน",
  "Connected. Your first backup goes up now.": "เชื่อมต่อแล้ว ข้อมูลสำรองแรกกำลังอัปโหลด",
  "Disconnect Strava?": "ยกเลิกการเชื่อมต่อ Strava ไหม?",
