  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "รู้ได้จากในกระเป๋าว่าจะอยู่ที่เดิม กลับไปต้นซูเปอร์เซ็ต หรือไปต่อ",
  "Last backup {0}": "สำรองล่าสุด {0}",
  "Last fetched by a calendar {0}": "ปฏิทินดึงข้อมูลล่าสุด {0}",
  "Last upload": "อัปโหลดล่าสุด",
  "Leave empty to keep the one saved": "เว้นว่างไว้เพื่อใช้ค่าที่บันทึกไว้",
  "Like 3-1-1-0: three seconds down, one at the bottom, one up.": "เช่น 3-1-1-0: ลงสามวินาที ค้างล่างหนึ่ง ขึ้นหนึ่ง",
  "Like the exercise ({0})": "ตามท่าออกกำลังกาย ({0})",
  "Link copied. Paste it into your calendar app.": "คัดลอกลิงก์แล้ว วางในแอปปฏิทินของคุณได้เลย",
  "Make a new link": "สร้างลิงก์ใหม่",
  "Make a new link?": "สร้างลิงก์ใหม่ไหม?",
  "Make my calendar link": "สร้างลิงก์ปฏิทินของฉัน",
  "New link made. The old one is gone.": "สร้างลิงก์ใหม่แล้ว ลิงก์เก่าใช้ไม่ได้แล้ว",
  "Nextcloud or any WebDAV folder, once a day": "Nextcloud หรือโฟลเดอร์ WebDAV ใดก็ได้ วันละครั้ง",
  "No backup yet": "ยังไม่มีข้อมูลสำรอง",
  "No calendar has fetched it yet.": "ยังไม่มีปฏิทินไหนดึงข้อมูล",
