  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "สำหรับการ์ดฟอร์มวันนี้ในสถิติและเช็กอินของคุณ อ่านบนโทรศัพท์เครื่องนี้เท่านั้น ไม่ส่งไปที่ไหน",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "แตะสี่ครั้งเรื่องการนอน พลังงาน อาการปวดกล้ามเนื้อ และความเครียด วันที่หนัก openGym จะเสนอให้เบาลง และหลังไม่กี่สัปดาห์คุณจะเห็นว่าวันดี ๆ ของคุณมีอะไรเหมือนกัน",
