  "Someone else set it up on this device, so nothing of yours goes to their folder. Disconnect it to set up your own.": "มีคนอื่นตั้งค่าไว้บนอุปกรณ์นี้ ข้อมูลของคุณจึงไม่ถูกส่งไปที่โฟลเดอร์ของเขา ยกเลิกการเชื่อมต่อเพื่อตั้งค่าของคุณเอง",
  "Routine from a past workout": "รูทีนจากการเล่นครั้งก่อน",
  "From a past workout": "จากการเล่นครั้งก่อน",
  "Pick one you did, imported ones too. Its exercises and sets become a routine you can tweak.": "เลือกครั้งที่คุณเคยเล่น รวมถึงที่นำเข้ามา ท่าและเซ็ตของมันจะกลายเป็นรูทีนที่ปรับแต่งได้",
  "That workout has no exercises to copy.": "การเล่นครั้งนั้นไม่มีท่าให้คัดลอก",
  "Saved as a routine. Your workout stays as it was.": "บันทึกเป็นรูทีนแล้ว การเล่นของคุณยังอยู่เหมือนเดิม",
  "Nothing logged yet. Train once, or import your history, and it shows up here.": "ยังไม่มีอะไรบันทึกไว้ เล่นสักครั้งหรือนำเข้าประวัติ แล้วจะขึ้นที่นี่",
  // --- text size and forgotten workouts (watch-polish-146) ---
  "Smallest": "เล็กที่สุด",
  "Largest": "ใหญ่ที่สุด",
  "Follows your phone’s text size, now {0}.": "ตามขนาดตัวอักษรของโทรศัพท์ ตอนนี้ {0}",
  "Big enough to read from the bench.": "ใหญ่พอให้อ่านจากม้านั่ง",
  "Heavy squats, then pizza.": "สควอตหนัก ๆ แล้วไปกินพิซซ่า",
  "This is how the app reads now.": "แอปจะอ่านแบบนี้",
  "font text size bigger smaller letters": "แบบอักษร ตัวอักษร ขนาด ใหญ่ขึ้น เล็กลง",
  "forgotten workout auto finish": "การฝึกที่ลืม จบอัตโนมัติ",
  "Ask “Still training?”": "ถาม “ยังฝึกอยู่ไหม?”",
  "End by itself when I leave the gym": "จบเองเมื่อฉันออกจากยิม",
  "Time to answer": "เวลาตอบ",
  "Finish the workout you’re on first, then reopen this one.": "จบการฝึกที่กำลังทำก่อน แล้วค่อยเปิดอันนี้ใหม่",
  "Back in the workout. Pick up where you left off.": "กลับมาที่การฝึกแล้ว ทำต่อจากที่ค้างไว้ได้เลย",
  "Ended by itself when you left the gym": "จบเองตอนที่คุณออกจากยิม",
  "Ended by itself after a quiet spell": "จบเองหลังจากเงียบไปพักหนึ่ง",
  "Saved as ending at {0}, after your last set and its rest.": "บันทึกว่าจบเวลา {0} หลังเซ็ตสุดท้ายและช่วงพักของมัน",
  "Reopen workout": "เปิดการฝึกอีกครั้ง",
  "Still training?": "ยังฝึกอยู่ไหม?",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "ไม่มีเซ็ตมา {0} นาทีแล้ว ถ้าเสร็จแล้ว จะปิดให้ใน {1} นาที โดยจบที่เซ็ตสุดท้าย",
  "Looks like you left the gym": "ดูเหมือนคุณออกจากยิมแล้ว",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "จบการฝึกตอนนี้เลยไหม? ไม่งั้นจะจบเองใน {0} นาที",
  "Keep going": "ทำต่อ",
  "Finish now": "จบตอนนี้",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "จบการฝึกตอนนี้เลยไหม? ไม่งั้นจะจบเองเวลา {0}",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "ไม่มีการบันทึกมาสักพัก ถ้าเสร็จแล้ว จะจบเองเวลา {0} บันทึกที่เซ็ตสุดท้าย",
  "Forgotten workouts": "การฝึกที่ลืมไว้",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "ถ้าไม่มีใครตอบ จะจบเองและไม่ทิ้งอะไรเลย เวลาจบคือเซ็ตสุดท้ายบวกช่วงพัก เวลาจึงยังตรงจริง เปิดใหม่ได้จากประวัติภายในหนึ่งวัน นาฬิกาก็ถามด้วย",
  "Never asks and never ends one by itself.": "ไม่ถามและไม่จบอะไรเองเลย",
  "The default. Long enough for a chat at the water fountain.": "ค่าเริ่มต้น นานพอให้คุยเล่นที่ตู้น้ำ",
  "Asks the moment your phone walks out of your gym, then wraps up.": "ถามทันทีที่โทรศัพท์เดินออกจากยิม แล้วปิดให้",
  "Needs the gym reminder: {0}.": "ต้องเปิดการแจ้งเตือนยิม: {0}",
  "Save to Photos": "บันทึกลงรูปภาพ",
  "Save image": "บันทึกรูป",
  "Saved to Photos": "บันทึกลงรูปภาพแล้ว",
  "Could not save the picture.": "บันทึกรูปไม่ได้",
  "openGym may not add pictures to Photos. You can allow it in the phone settings.": "openGym ไม่ได้รับอนุญาตให้เพิ่มรูปลงในรูปภาพ คุณอนุญาตได้ในการตั้งค่าโทรศัพท์",
  "Sections": "ส่วนต่าง ๆ",
  "More sections": "ส่วนอื่น ๆ",
  "Choose routine": "เลือกรูทีน",
  "{0}, show all tabs": "{0} แสดงแท็บทั้งหมด",
  "Resume workout, {0} elapsed": "ออกกำลังต่อ ผ่านไป {0}",
  "Workout started": "เริ่มออกกำลังกายแล้ว",
